const CFG = $('Config').first().json;
const nowIso = () => new Date().toISOString();
const lc = (s) => String(s ?? '').trim().toLowerCase();
function zoneFor(tz) {
  const z = String(tz || '').trim();
  if (z && DateTime.now().setZone(z).isValid) return z;
  return CFG.DEFAULT_TIMEZONE || 'UTC';
}
function addBusinessDays(dt, n) {
  let d = dt; let added = 0;
  while (added < n) { d = d.plus({ days: 1 }); if (d.weekday <= 5) added++; }
  return d;
}
function nextFollowupIso(businessDays, tz) {
  const testMin = Number(CFG.TEST_FOLLOWUP_DELAY_MINUTES || 0);
  if (testMin > 0) return DateTime.utc().plus({ minutes: testMin }).toISO();
  return addBusinessDays(DateTime.now().setZone(zoneFor(tz)), Number(businessDays)).toUTC().toISO();
}
function sendWindow(tz) {
  const zone = zoneFor(tz);
  const local = DateTime.now().setZone(zone);
  if (CFG.IGNORE_SEND_WINDOW === true || String(CFG.IGNORE_SEND_WINDOW).toLowerCase() === 'true') {
    return { ok: true, zone, local: local.toFormat('ccc HH:mm') };
  }
  const ok = local.weekday <= 5 && local.hour >= Number(CFG.SEND_WINDOW_START_HOUR ?? 9) && local.hour < Number(CFG.SEND_WINDOW_END_HOUR ?? 17);
  return { ok, zone, local: local.toFormat('ccc HH:mm') };
}
function rowsOf(nodeName) {
  try { return $(nodeName).all().map(i => i.json).filter(r => r && Object.keys(r).length); } catch (e) { return []; }
}
function sentTodayCount(eventRows) {
  const zone = zoneFor(CFG.DEFAULT_TIMEZONE);
  const today = DateTime.now().setZone(zone).toISODate();
  return eventRows.filter(r => ['sent', 'followup_sent', 'reply_sent'].includes(lc(r.event)) && r.timestamp &&
    DateTime.fromISO(String(r.timestamp)).setZone(zone).toISODate() === today).length;
}
function isSuppressed(email, domain, suppRows) {
  const e = lc(email); const d = lc(domain);
  return suppRows.some(r => (lc(r.email) && lc(r.email) === e) || (!lc(r.email) && lc(r.domain) && lc(r.domain) === d));
}
const safe = (s) => String(s ?? '').replace(/[{}]/g, ' ');

const prospects = rowsOf('Load Prospects').filter(r => r.prospect_id);
const byEmail = new Map(prospects.map(p => [lc(p.email), p]));
const byThread = new Map(prospects.filter(p => p.thread_id).map(p => [String(p.thread_id), p]));
const me = lc(CFG.SENDER_EMAIL);
const out = [];
for (const item of $('Gmail Trigger: Unread Inbox').all()) {
  const m = item.json;
  const fromAddr = lc((m.from && m.from.value && m.from.value[0] && m.from.value[0].address) || String(m.From || m.from || '').replace(/.*</, '').replace(/>.*/, ''));
  const subject = String(m.subject || m.Subject || '');
  const text = String(m.text || m.snippet || '').slice(0, 8000);
  if (!fromAddr || fromAddr === me) continue;
  const isBounce = /mailer-daemon|postmaster/.test(fromAddr) || /(delivery status notification|undeliverable|mail delivery failed|returned mail|delivery failure|address not found)/i.test(subject);
  let p = byThread.get(String(m.threadId)) || byEmail.get(fromAddr);
  if (!p && isBounce) p = prospects.find(x => x.email && text.toLowerCase().includes(lc(x.email)));
  if (!p) continue;                       // not a prospect: leave the email alone (stays unread)
  if (['unsubscribed', 'bounced'].includes(p.status)) continue;
  // drop quoted history so the classifier only sees the new reply
  const fresh = text.split(/\n(?:On .{5,200}wrote:|-{2,} ?Original Message|From: .+\nSent: )/i)[0].replace(/^>.*$/gm, '').trim();
  out.push({ json: { prospect_id: p.prospect_id, status_at_match: p.status, email: p.email, domain: p.domain,
    first_name: safe(p.first_name), company: safe(p.company), timezone: p.timezone,
    gmail_id: m.id, thread_id: m.threadId, from: fromAddr, subject: safe(subject).slice(0, 300),
    reply_text: safe(fresh || text).slice(0, 4000), is_bounce: isBounce } });
}
return out;

parameters.text:
=Classify this email reply to a cold outreach message from {{ $('Config').first().json.SENDER_NAME }}, who builds small business automations and offered to send a 2-minute video.

From: {{ $('Loop Replies').first(1).json.from }}
Subject: {{ $('Loop Replies').first(1).json.subject }}
Prospect first name: {{ $('Loop Replies').first(1).json.first_name }} | Company: {{ $('Loop Replies').first(1).json.company }}

Reply text:
{{ $('Loop Replies').first(1).json.reply_text }}

Categories: interested (wants the video, a call or more info), question (asks something specific), objection (pushback on price, need, timing with reasons, or trust), not_now (polite not right now or later this year), unsubscribe (asks to stop, remove, not interested at all), out_of_office (automatic absence reply), bounce (delivery failure notice), other (anything else).
summary: one sentence.
suggested_reply: only for interested, question or objection. Plain text, 40 to 90 words, warm and direct, answers what they said. If they ask about price or cost, answer directly: give a typical starting range, or offer a short call and include a range. Do not make a hard promise (no fixed quote, no guaranteed date, no guaranteed result). No lists, no links, no buzzwords, starts with Hi and the first name, ends with Best, and {{ $('Config').first().json.SENDER_NAME }} on separate lines. Otherwise an empty string.
return_date: for out_of_office the date they are back as YYYY-MM-DD if stated (today is {{ $now.toISODate() }}), otherwise an empty string.

