{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": [
        "interested",
        "question",
        "objection",
        "not_now",
        "unsubscribe",
        "out_of_office",
        "bounce",
        "other"
      ]
    },
    "summary": {
      "type": "string",
      "description": "one sentence summary of the reply"
    },
    "suggested_reply": {
      "type": "string",
      "description": "plain-text reply for interested, question or objection; empty string otherwise"
    },
    "return_date": {
      "type": "string",
      "description": "YYYY-MM-DD the person is back, only for out_of_office, else empty string"
    }
  },
  "required": [
    "category",
    "summary",
    "suggested_reply",
    "return_date"
  ]
}

